import { provideHttpClient } from '@angular/common/http';
import { provideHttpClientTesting } from '@angular/common/http/testing';
import { TestBed } from '@angular/core/testing';
import { ActivatedRoute, convertToParamMap, provideRouter } from '@angular/router';
import { BookingService } from '../core/booking.service';
import { Checkout } from './checkout';

describe('Checkout', () => {
  function setup() {
    sessionStorage.clear();
    TestBed.configureTestingModule({
      providers: [
        provideRouter([]),
        provideHttpClient(),
        provideHttpClientTesting(),
        { provide: ActivatedRoute, useValue: { snapshot: { paramMap: convertToParamMap({ id: '1' }) } } },
      ],
    });
    const booking = TestBed.inject(BookingService);
    booking.startFor(1);
    booking.add('R7C12');
    booking.add('R15C1');
    const fixture = TestBed.createComponent(Checkout);
    fixture.detectChanges();
    return { fixture, el: fixture.nativeElement as HTMLElement };
  }

  const q = (el: HTMLElement, id: string) => el.querySelector<HTMLElement>(`[data-testid="${id}"]`);

  it('shows the total and validates on pay', async () => {
    const { fixture, el } = setup();
    expect(q(el, 'pay-button')!.textContent!.trim()).toBe('Pay 121.00 PLN');
    expect(q(el, 'first-name-error')).toBeNull();
    q(el, 'pay-button')!.click();
    fixture.detectChanges();
    await fixture.whenStable();
    fixture.detectChanges();
    expect(q(el, 'first-name-error')!.textContent!.trim()).toBe('First name is required');
    expect(q(el, 'confirm-email-error')!.textContent!.trim()).toBe('Confirm email is required');
    expect(q(el, 'terms-error')!.textContent!.trim()).toBe('You must accept the terms and conditions');
    expect(q(el, 'phone-error')).toBeNull();
  });

  it('checks email, confirmation and phone and keeps values', async () => {
    const { fixture, el } = setup();
    const type = (id: string, value: string) => {
      const input = q(el, id) as HTMLInputElement;
      input.value = value;
      input.dispatchEvent(new Event('input'));
      input.dispatchEvent(new Event('blur'));
      fixture.detectChanges();
    };
    type('email-input', 'a@b');
    type('confirm-email-input', 'a@b.com');
    type('phone-input', '12345');
    expect(q(el, 'email-error')!.textContent!.trim()).toBe('Enter a valid email address');
    expect(q(el, 'confirm-email-error')!.textContent!.trim()).toBe('Email addresses do not match');
    expect(q(el, 'phone-error')!.textContent!.trim()).toBe('Phone number must be exactly 9 digits');
    type('email-input', 'a@b.com');
    expect(q(el, 'email-error')).toBeNull();
    expect(q(el, 'confirm-email-error')).toBeNull();
    expect(TestBed.inject(BookingService).booking()!.form.email).toBe('a@b.com');
  });
});

import { provideHttpClient } from '@angular/common/http';
import { HttpTestingController, provideHttpClientTesting } from '@angular/common/http/testing';
import { TestBed } from '@angular/core/testing';
import { provideNativeDateAdapter } from '@angular/material/core';
import { provideRouter } from '@angular/router';
import { toIsoDate } from '../core/dates';
import { MovieList } from './movie-list';

describe('MovieList', () => {
  const q = (el: HTMLElement, id: string) => Array.from(el.querySelectorAll<HTMLElement>(`[data-testid="${id}"]`));

  it('lists movies with screenings of the selected day, ordered by time', () => {
    TestBed.configureTestingModule({
      providers: [provideRouter([]), provideHttpClient(), provideHttpClientTesting(), provideNativeDateAdapter()],
    });
    const fixture = TestBed.createComponent(MovieList);
    const el = fixture.nativeElement as HTMLElement;
    fixture.detectChanges();
    expect(q(el, 'movies-loading').length).toBe(1);
    expect(q(el, 'day-button').length).toBe(5);
    expect(q(el, 'day-button')[0].textContent!.trim()).toBe('Today');
    expect(q(el, 'day-button')[0].dataset['selected']).toBe('true');

    const today = toIsoDate(new Date());
    const http = TestBed.inject(HttpTestingController);
    http.expectOne('http://localhost:3000/movies').flush([
      { id: 1, title: 'A', genre: 'Drama', runtimeMinutes: 128, format: 'PL dubbing' },
      { id: 2, title: 'B', genre: 'Sci-Fi', runtimeMinutes: 90, format: 'PL subtitles' },
    ]);
    http.expectOne('http://localhost:3000/screenings').flush([
      { id: 1, movieId: 1, date: today, time: '18:00', occupiedSeats: [] },
      { id: 2, movieId: 1, date: today, time: '16:00', occupiedSeats: [] },
      { id: 3, movieId: 2, date: '2020-01-01', time: '10:00', occupiedSeats: [] },
    ]);
    fixture.detectChanges();
    expect(q(el, 'movies-loading').length).toBe(0);
    expect(q(el, 'movie-card').length).toBe(1);
    expect(q(el, 'screening-button').map((b) => b.textContent!.trim())).toEqual(['16:00', '18:00']);
    expect(q(el, 'movie-runtime')[0].textContent).toBe('128 min');
  });
});

import { provideHttpClient } from '@angular/common/http';
import { HttpTestingController, provideHttpClientTesting } from '@angular/common/http/testing';
import { TestBed } from '@angular/core/testing';
import { ActivatedRoute, convertToParamMap, provideRouter } from '@angular/router';
import { SeatMap } from './seat-map';

describe('SeatMap', () => {
  function setup() {
    sessionStorage.clear();
    TestBed.configureTestingModule({
      providers: [
        provideRouter([]),
        provideHttpClient(),
        provideHttpClientTesting(),
        { provide: ActivatedRoute, useValue: { snapshot: { paramMap: convertToParamMap({ id: '1' }) } } },
      ],
    });
    const fixture = TestBed.createComponent(SeatMap);
    const http = TestBed.inject(HttpTestingController);
    http
      .expectOne('http://localhost:3000/screenings/1')
      .flush({ id: 1, movieId: 1, date: '2026-09-15', time: '16:00', occupiedSeats: ['R3C7', 'R15C5', 'R15C6'] });
    http
      .expectOne('http://localhost:3000/movies/1')
      .flush({ id: 1, title: 'X', genre: 'Drama', runtimeMinutes: 100, format: 'PL dubbing' });
    fixture.detectChanges();
    return { fixture, el: fixture.nativeElement as HTMLElement };
  }

  const q = (el: HTMLElement, id: string) => Array.from(el.querySelectorAll<HTMLElement>(`[data-testid="${id}"]`));

  it('draws the auditorium', () => {
    const { el } = setup();
    expect(q(el, 'seat-row').length).toBe(15);
    expect(q(el, 'seat').length + q(el, 'couch').length).toBe(308);
    expect(q(el, 'couch').length).toBe(12);
    expect(q(el, 'aisle').length).toBe(30);
    expect(q(el, 'seat').filter((s) => s.dataset['state'] === 'accessible').length).toBe(6);
    expect(q(el, 'seat-map-subtitle')[0].textContent).toBe('Show Date: Tuesday 15 Sep 16:00');
    expect(q(el, 'couch').filter((c) => c.dataset['state'] === 'unavailable').length).toBe(1);
  });

  it('selects, caps and lists seats', () => {
    const { fixture, el } = setup();
    const seat = (row: number, col: number) =>
      q(el, 'seat').find((s) => s.dataset['row'] === String(row) && s.dataset['column'] === String(col))!;
    const click = (e: HTMLElement) => {
      e.click();
      fixture.detectChanges();
    };
    click(seat(7, 12));
    click(seat(7, 11));
    click(q(el, 'couch')[0]);
    expect(q(el, 'selected-seats-count')[0].textContent).toBe('Selected seats: 4');
    expect(q(el, 'selected-seats-row').map((r) => r.textContent)).toEqual(['Row 7: 11, 12', 'Row 15: 1-2']);
    click(seat(7, 12));
    expect(q(el, 'selected-seats-count')[0].textContent).toBe('Selected seats: 3');
    click(seat(3, 7));
    expect(seat(3, 7).dataset['state']).toBe('unavailable');
    for (let c = 5; c <= 11; c++) click(seat(2, c));
    expect(q(el, 'selected-seats-count')[0].textContent).toBe('Selected seats: 10');
    click(seat(2, 12));
    expect(q(el, 'selected-seats-count')[0].textContent).toBe('Selected seats: 10');
    expect(seat(2, 12).dataset['state']).toBe('available');
  });
});
